package com.gpcbellary.cms.model;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="admissions") public class Admission {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private String applicationNo;
 private String applicantName,fatherName,motherName,gender,phone,email,branch,previousQualification,address,status; private LocalDate applicationDate;
 public Admission(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getApplicationNo(){return applicationNo;} public void setApplicationNo(String v){applicationNo=v;} public String getApplicantName(){return applicantName;} public void setApplicantName(String v){applicantName=v;} public String getFatherName(){return fatherName;} public void setFatherName(String v){fatherName=v;} public String getMotherName(){return motherName;} public void setMotherName(String v){motherName=v;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getBranch(){return branch;} public void setBranch(String v){branch=v;} public String getPreviousQualification(){return previousQualification;} public void setPreviousQualification(String v){previousQualification=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDate getApplicationDate(){return applicationDate;} public void setApplicationDate(LocalDate v){applicationDate=v;}
}
